*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; overflow-x: hidden; font-family: var(--font-body, Inter, 'Noto Sans TC', sans-serif); }
.page { max-width: 1100px; margin: 0 auto; padding: var(--space-6) var(--space-4); display: grid; gap: var(--space-4); min-width: 0; }
.page-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-4); }
.page-head h1 { margin: 0; font-size: 2rem; line-height: 1.3; }
section[data-eval-state] { display: grid; gap: var(--space-4); min-width: 0; }
.toolbar { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); gap: var(--space-4); }
.count { margin: 0; color: var(--muted); font-size: .875rem; }
.table-wrap { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-card); padding: var(--space-2) var(--space-4); }
.orders { width: 100%; border-collapse: collapse; font-size: .875rem; line-height: 1.6; }
.orders th { text-align: left; color: var(--muted); font-weight: 500; }
.orders th, .orders td { padding: var(--space-3) var(--space-2); border-bottom: 1px solid var(--border); vertical-align: middle; overflow-wrap: anywhere; }
.orders tbody tr:last-child td { border-bottom: 0; }
.orders .num { text-align: right; font-variant-numeric: tabular-nums; }
.row-actions { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.row-actions .luca-button { padding: var(--space-1) var(--space-4); }
.badge { display: inline-block; padding: 0 var(--space-3); border: 1px solid currentColor; border-radius: 999px; background: var(--surface); font-size: .8125rem; font-weight: 500; white-space: nowrap; }
.badge-pending { color: var(--warning); }
.badge-paid { color: var(--success); }
.badge-shipped { color: var(--accent-hover); }
.badge-cancelled { color: var(--muted); }
.notice { min-width: 0; }
.modal { width: min(28rem, calc(100vw - 2rem)); max-height: calc(100vh - 2rem); overflow: auto; padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-card); background: var(--surface); color: var(--text); }
.modal::backdrop { background: rgba(0, 0, 0, .5); }
.modal h2 { margin: 0 0 var(--space-4); font-size: 1.5rem; line-height: 1.4; }
.form { display: grid; gap: var(--space-4); }
.actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: var(--space-3); margin-top: var(--space-2); }

@media (max-width: 760px) {
  .page { padding: var(--space-4) var(--space-3); }
  .page-head h1 { font-size: 1.5rem; }
  .toolbar { grid-template-columns: minmax(0, 1fr); }
  .table-wrap { padding: var(--space-2) var(--space-3); }
  .orders thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .orders, .orders tbody, .orders tr, .orders td { display: block; width: 100%; }
  .orders tr { padding: var(--space-3) 0; border-bottom: 1px solid var(--border); }
  .orders tbody tr:last-child { border-bottom: 0; }
  .orders td { display: flex; justify-content: space-between; align-items: center; gap: var(--space-3); border: 0; padding: var(--space-1) 0; text-align: right; }
  .orders td::before { content: attr(data-label); color: var(--muted); font-weight: 500; text-align: left; flex-shrink: 0; }
  .orders .num { text-align: right; }
  .orders td.row-actions { justify-content: flex-end; }
  .orders td.row-actions::before { display: none; }
}

